    private void button1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_button1ActionPerformed
        String codigo = txtCodigo.getText().trim();
        String nombre = txtNombre.getText().trim();
        nombre = capitalizarNombre(nombre);
        
        if (codigo.isEmpty() || nombre.isEmpty()) {
            javax.swing.JOptionPane.showMessageDialog(this,
            "Debe ingresar el código y el nombre del estudiante.",
            "Datos incompletos", javax.swing.JOptionPane.WARNING_MESSAGE);
        return;
        }
        if (existeCodigo(codigo)) {
        javax.swing.JOptionPane.showMessageDialog(this,
            "Ya existe un estudiante registrado con el código \"" + codigo + "\".",
            "Código duplicado", javax.swing.JOptionPane.WARNING_MESSAGE);
            return;
        }
        Double nota1 = validarNota(txtNota1.getText().trim(), "Primera nota");
            if (nota1 == null) return;
        Double nota2 = validarNota(txtNota2.getText().trim(), "Segunda nota");
            if (nota2 == null) return;
        Double nota3 = validarNota(txtNota3.getText().trim(), "Tercera nota");
            if (nota3 == null) return;

        double definitiva = (nota1 * 0.30) + (nota2 * 0.30) + (nota3 * 0.40);
        definitiva = Math.round(definitiva * 100.0) / 100.0;

        String estado = (definitiva >= 3.0) ? "Aprobó" : "Reprobó";

        javax.swing.table.DefaultTableModel modelo =
        (javax.swing.table.DefaultTableModel) tablaEstudiantes.getModel();
        modelo.addRow(new Object[]{codigo, nombre, nota1, nota2, nota3, definitiva, estado});

        limpiarCampos();
    }//GEN-LAST:event_button1ActionPerformed

