    private Double validarNota(String texto, String nombreCampo) {
        if (texto.isEmpty()) {
        javax.swing.JOptionPane.showMessageDialog(this,
                "El campo \"" + nombreCampo + "\" no puede estar vacío.",
                "Dato faltante", javax.swing.JOptionPane.WARNING_MESSAGE);
        return null;
    }
        try {
            double valor = Double.parseDouble(texto.replace(",", "."));
        if (valor < 0.0 || valor > 5.0) {
            javax.swing.JOptionPane.showMessageDialog(this,
                    nombreCampo + " debe estar entre 0.0 y 5.0.",
                    "Nota fuera de rango", javax.swing.JOptionPane.WARNING_MESSAGE);
            return null;
        }
        return valor;
    } catch (NumberFormatException ex) {
        javax.swing.JOptionPane.showMessageDialog(this,
                nombreCampo + " debe ser un valor numérico válido.",
                "Formato inválido", javax.swing.JOptionPane.ERROR_MESSAGE);
        return null;
    }
}
    private boolean existeCodigo(String codigo) {
    javax.swing.table.DefaultTableModel modelo =
            (javax.swing.table.DefaultTableModel) tablaEstudiantes.getModel();
    for (int i = 0; i < modelo.getRowCount(); i++) {
        Object valorCelda = modelo.getValueAt(i, 0); // columna 0 = Código
        if (valorCelda != null && valorCelda.toString().equalsIgnoreCase(codigo)) {
            return true;
        }
    }
    return false;
}
    private String capitalizarNombre(String texto) {
        if (texto.isEmpty()) {
        return texto;
    }
    String[] palabras = texto.toLowerCase().split("\\s+");
    StringBuilder resultado = new StringBuilder();
        for (String palabra : palabras) {
            if (!palabra.isEmpty()) {
            resultado.append(Character.toUpperCase(palabra.charAt(0)))
                      .append(palabra.substring(1))
                      .append(" ");
        }
    }
    return resultado.toString().trim();
}
    private void limpiarCampos() {
        txtCodigo.setText("");
        txtNombre.setText("");
        txtNota1.setText("");
        txtNota2.setText("");
        txtNota3.setText("");
        txtCodigo.requestFocus();
}
